package recoverytest

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math/rand/v2"
	"os"
	"path/filepath"
	"sort"
	"testing"

	"github.com/klauspost/compress/zstd"
)

// The fixtures under testdata/builtin are generated by this file and
// committed, so a reader test runs over real bytes on disk and not over bytes
// the test built a moment ago with the same library it is judging.
//
// Regenerate with:
//
//	RETND_GEN_BUILTIN_FIXTURES=1 go test ./internal/recoverytest -run TestGenerateBuiltinFixtures
//
// manifest.json carries each file's SHA-256, and TestBuiltinFixturesMatchTheirManifest
// refuses a fixture that was edited by hand or regenerated by a different
// library version without the manifest being re-captured.

const fixtureDir = "testdata/builtin"

func fxRand(seed uint64) *rand.Rand { return rand.New(rand.NewPCG(seed, seed^0x9e3779b97f4a7c15)) }

// fxText is compressible, deterministic filler.
func fxText(n int, seed uint64) []byte {
	r := fxRand(seed)
	words := []string{"backup", "restore", "archive", "segment", "ledger", "orders", "customers", "payload", "index", "page"}
	var b bytes.Buffer
	for b.Len() < n {
		fmt.Fprintf(&b, "%s-%d %s\n", words[r.IntN(len(words))], r.IntN(100000), words[r.IntN(len(words))])
	}
	return b.Bytes()[:n]
}

func fxRandom(n int, seed uint64) []byte {
	r := fxRand(seed)
	b := make([]byte, n)
	for i := range b {
		b[i] = byte(r.Uint32())
	}
	return b
}

func fxGzip(t *testing.T, parts ...[]byte) []byte {
	t.Helper()
	var out bytes.Buffer
	for _, p := range parts {
		zw := gzip.NewWriter(&out)
		if _, err := zw.Write(p); err != nil {
			t.Fatal(err)
		}
		if err := zw.Close(); err != nil {
			t.Fatal(err)
		}
	}
	return out.Bytes()
}

func fxZstd(t *testing.T, crc bool, p []byte) []byte {
	t.Helper()
	var out bytes.Buffer
	zw, err := zstd.NewWriter(&out, zstd.WithEncoderCRC(crc), zstd.WithEncoderConcurrency(1))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := zw.Write(p); err != nil {
		t.Fatal(err)
	}
	if err := zw.Close(); err != nil {
		t.Fatal(err)
	}
	return out.Bytes()
}

type fxEntry struct {
	hdr  tar.Header
	data []byte
}

func fxTar(t *testing.T, terminate bool, entries ...fxEntry) []byte {
	t.Helper()
	var out bytes.Buffer
	tw := tar.NewWriter(&out)
	for _, e := range entries {
		h := e.hdr
		h.Size = int64(len(e.data))
		h.Mode = 0o644
		h.Typeflag = tar.TypeReg
		if err := tw.WriteHeader(&h); err != nil {
			t.Fatal(err)
		}
		if _, err := tw.Write(e.data); err != nil {
			t.Fatal(err)
		}
	}
	if err := tw.Flush(); err != nil {
		t.Fatal(err)
	}
	if terminate {
		if err := tw.Close(); err != nil {
			t.Fatal(err)
		}
	}
	return out.Bytes()
}

func fxPlainEntries() []fxEntry {
	return []fxEntry{
		{hdr: tar.Header{Name: "db/base.sql"}, data: fxText(40000, 11)},
		{hdr: tar.Header{Name: "db/roles.sql"}, data: fxText(3000, 12)},
		{hdr: tar.Header{Name: "db/blob.bin"}, data: fxRandom(9000, 13)},
	}
}

// fxCraftedZstd builds a frame header by hand: a Window_Descriptor byte, an
// optional dictionary id, and one empty last raw block. klauspost's encoder
// cannot write a 2 GiB window or a dictionary frame, and the decoder refuses
// both at the header, which is what the fixtures are for.
func fxCraftedZstd(windowDescriptor byte, dictID *byte) []byte {
	b := []byte{0x28, 0xb5, 0x2f, 0xfd}
	fhd := byte(0)
	if dictID != nil {
		fhd |= 1
	}
	b = append(b, fhd, windowDescriptor)
	if dictID != nil {
		b = append(b, *dictID)
	}
	return append(b, 0x01, 0x00, 0x00)
}

func fxSkippable(n int) []byte {
	b := make([]byte, 8, 8+n)
	binary.LittleEndian.PutUint32(b, 0x184D2A50)
	binary.LittleEndian.PutUint32(b[4:], uint32(n))
	return append(b, make([]byte, n)...)
}

func flipAt(b []byte, i int) []byte {
	c := append([]byte(nil), b...)
	c[i] ^= 0xff
	return c
}

func buildBuiltinFixtures(t *testing.T) map[string][]byte {
	t.Helper()
	files := map[string][]byte{}

	payload := fxText(150000, 1)
	gz := fxGzip(t, payload)
	files["gz-single.gz"] = gz
	files["gz-multi.gz"] = fxGzip(t, fxText(50000, 2), fxText(50000, 3), fxText(50000, 4))
	files["gz-truncated.gz"] = gz[:len(gz)-9]
	files["gz-flipped.gz"] = flipAt(gz, len(gz)/2)
	files["gz-trailing-garbage.gz"] = append(append([]byte(nil), gz...), []byte("this is not a gzip member, it is trailing garbage")...)

	zc := fxZstd(t, true, fxText(300000, 5))
	files["zst-checksum.zst"] = zc
	files["zst-nochecksum.zst"] = fxZstd(t, false, fxText(300000, 6))
	files["zst-skippable.zst"] = append(append(fxSkippable(24), fxZstd(t, true, fxText(60000, 7))...), fxSkippable(5)...)
	files["zst-truncated.zst"] = zc[:len(zc)/2]
	// Incompressible bytes go out as a stored block, so a flipped byte inside
	// it is something only the content checksum can notice.
	stored := fxZstd(t, true, fxRandom(8192, 8))
	files["zst-flipped.zst"] = flipAt(stored, len(stored)/2)
	files["zst-window2g.zst"] = fxCraftedZstd(21<<3, nil) // 2^(10+21) = 2 GiB
	one := byte(1)
	files["zst-dict.zst"] = fxCraftedZstd(0x00, &one)

	plain := fxTar(t, true, fxPlainEntries()...)
	files["tar-plain.tar"] = plain
	files["tar-pax.tar"] = func() []byte {
		var out bytes.Buffer
		tw := tar.NewWriter(&out)
		long := "pax/" + string(bytes.Repeat([]byte("deep/"), 60)) + "file.txt"
		h := tar.Header{Name: long, Size: 100, Mode: 0o644, Typeflag: tar.TypeReg, Format: tar.FormatPAX, PAXRecords: map[string]string{"comment": "pax record"}}
		if err := tw.WriteHeader(&h); err != nil {
			t.Fatal(err)
		}
		tw.Write(fxText(100, 21))
		tw.Close()
		return out.Bytes()
	}()
	files["tar-gnu-longname.tar"] = func() []byte {
		var out bytes.Buffer
		tw := tar.NewWriter(&out)
		long := "gnu/" + string(bytes.Repeat([]byte("segment/"), 40)) + "file.txt"
		h := tar.Header{Name: long, Size: 100, Mode: 0o644, Typeflag: tar.TypeReg, Format: tar.FormatGNU}
		if err := tw.WriteHeader(&h); err != nil {
			t.Fatal(err)
		}
		tw.Write(fxText(100, 22))
		tw.Close()
		return out.Bytes()
	}()
	files["tar-truncated-mid-entry.tar"] = plain[:512+20000]
	files["tar-no-terminator.tar"] = fxTar(t, false, fxPlainEntries()...)
	files["tar-dotdot-abs.tar"] = fxTar(t, true,
		fxEntry{hdr: tar.Header{Name: "../../etc/cron.d/evil"}, data: fxText(700, 31)},
		fxEntry{hdr: tar.Header{Name: "/abs/olute/path"}, data: fxText(700, 32)})

	targz := fxGzip(t, plain)
	files["targz-good.tar.gz"] = targz
	files["targz-truncated-outer.tar.gz"] = targz[:len(targz)-30]
	files["targz-truncated-inner.tar.gz"] = fxGzip(t, plain[:512+20000])
	tarzst := fxZstd(t, true, plain)
	files["tarzst-good.tar.zst"] = tarzst
	files["tarzst-truncated-outer.tar.zst"] = tarzst[:len(tarzst)-20]
	files["tarzst-truncated-inner.tar.zst"] = fxZstd(t, true, plain[:512+20000])

	files["gz-holding-zstd.gz"] = zc
	files["gz-random.gz"] = fxRandom(4096, 99)
	return files
}

func TestGenerateBuiltinFixtures(t *testing.T) {
	if os.Getenv("RETND_GEN_BUILTIN_FIXTURES") != "1" {
		t.Skip("set RETND_GEN_BUILTIN_FIXTURES=1 to regenerate testdata/builtin")
	}
	files := buildBuiltinFixtures(t)
	if err := os.MkdirAll(fixtureDir, 0o755); err != nil {
		t.Fatal(err)
	}
	sums := map[string]string{}
	names := make([]string, 0, len(files))
	for n, b := range files {
		if err := os.WriteFile(filepath.Join(fixtureDir, n), b, 0o644); err != nil {
			t.Fatal(err)
		}
		s := sha256.Sum256(b)
		sums[n] = hex.EncodeToString(s[:])
		names = append(names, n)
	}
	sort.Strings(names)
	m, _ := json.MarshalIndent(sums, "", "  ")
	if err := os.WriteFile(filepath.Join(fixtureDir, "manifest.json"), append(m, '\n'), 0o644); err != nil {
		t.Fatal(err)
	}
	t.Logf("wrote %d fixtures: %v", len(names), names)
}

func TestBuiltinFixturesMatchTheirManifest(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join(fixtureDir, "manifest.json"))
	if err != nil {
		t.Fatalf("the fixtures are generated and committed (see builtin_fixtures_gen_test.go): %v", err)
	}
	var want map[string]string
	if err := json.Unmarshal(raw, &want); err != nil {
		t.Fatal(err)
	}
	if len(want) < 26 {
		t.Fatalf("manifest lists %d fixtures, want the full set", len(want))
	}
	for n, sum := range want {
		b, err := os.ReadFile(filepath.Join(fixtureDir, n))
		if err != nil {
			t.Errorf("%s: %v", n, err)
			continue
		}
		got := sha256.Sum256(b)
		if hex.EncodeToString(got[:]) != sum {
			t.Errorf("%s no longer matches the manifest", n)
		}
	}
}
